// Extract just the stock spans (I don't need all the ugly JSX classes and raw html)
const regex = /<span title="([^"]+)" class="[^"]+ ppStock" style="([^"]+)"><span class="[^"]+ ppSym">([^<]+)<\/span><span class="[^"]+ ppPx">([^<]+)<\/span><span class="[^"]+ ppChg" style="([^"]+)">([^<]+)<span class="[^"]+" style="([^"]+)">([^<]+)<\/span><\/span><\/span>/g;
let match;
let stocks = [];
while ((match = regex.exec(html)) !== null) {
  stocks.push({
    title: match[1],
    sym: match[3],
    px: match[4],
    chg: match[6],
    chgStyle: match[5],
    pct: match[8],
    pctStyle: match[7]
  });
}

